-- =====================================================
-- ByteLab - Tienda de Hardware
-- Script de base de datos (SQL Server)
-- Ejecutar completo en SQL Server Management Studio
-- =====================================================

IF DB_ID('db_bytelab') IS NOT NULL
BEGIN
    ALTER DATABASE db_bytelab SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE db_bytelab;
END
GO
CREATE DATABASE db_bytelab;
GO
USE db_bytelab;
GO

CREATE TABLE [Roles] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [NombreRol] NVARCHAR(50) NOT NULL UNIQUE,
    [Descripcion] NVARCHAR(200) NULL,
    [SalarioEstimado] DECIMAL(18, 2) NULL,
    [EstadoActivo] BIT NOT NULL DEFAULT 0
);
GO

CREATE TABLE [Permisos] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Codigo] NVARCHAR(50) NOT NULL UNIQUE,
    [Nombre] NVARCHAR(100) NOT NULL,
    [Descripcion] NVARCHAR(200) NULL
);
GO

CREATE TABLE [RolesPermisos] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Rol] INT NOT NULL REFERENCES [Roles]([Id]),
    [Permiso] INT NOT NULL REFERENCES [Permisos]([Id]),
    CONSTRAINT UQ_RolesPermisos UNIQUE ([Rol], [Permiso])
);
GO

CREATE TABLE [Usuarios] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Rol] INT NOT NULL REFERENCES [Roles]([Id]),
    [NombreCompleto] NVARCHAR(100) NOT NULL,
    [Cedula] NVARCHAR(20) NOT NULL UNIQUE,
    [Correo] NVARCHAR(100) NOT NULL UNIQUE,
    [Contrasena] NVARCHAR(100) NOT NULL,
    [FechaRegistro] DATETIME2 NULL,
    [CuentaActiva] BIT NOT NULL DEFAULT 0
);
GO

CREATE TABLE [Auditorias] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Entidad] NVARCHAR(50) NOT NULL,
    [Accion] NVARCHAR(20) NOT NULL,
    [IdRegistro] INT NOT NULL,
    [Usuario] NVARCHAR(100) NOT NULL,
    [Fecha] DATETIME2 NOT NULL,
    [Datos] NVARCHAR(MAX) NULL
);
GO

CREATE TABLE [Sucursales] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [NombreSucursal] NVARCHAR(100) NOT NULL,
    [Direccion] NVARCHAR(200) NOT NULL,
    [Ciudad] NVARCHAR(50) NOT NULL,
    [TelefonoContacto] NVARCHAR(20) NULL,
    [HorarioAtencion] NVARCHAR(100) NOT NULL,
    [Latitud] FLOAT NULL,
    [Longitud] FLOAT NULL
);
GO

CREATE TABLE [Empleados] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Usuario] INT NOT NULL REFERENCES [Usuarios]([Id]),
    [Sucursal] INT NOT NULL REFERENCES [Sucursales]([Id]),
    [CargoPuesto] NVARCHAR(100) NOT NULL,
    [Salario] DECIMAL(18, 2) NOT NULL,
    [FechaContratacion] DATE NOT NULL
);
GO

CREATE TABLE [Clientes] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Usuario] INT NOT NULL REFERENCES [Usuarios]([Id]),
    [Telefono] NVARCHAR(20) NULL,
    [DireccionPrincipal] NVARCHAR(200) NULL,
    [FechaNacimiento] DATE NULL
);
GO

CREATE TABLE [Categorias] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Nombre] NVARCHAR(50) NOT NULL UNIQUE,
    [Descripcion] NVARCHAR(200) NULL
);
GO

CREATE TABLE [Marcas] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [NombreMarca] NVARCHAR(50) NOT NULL,
    [SitioWeb] NVARCHAR(200) NULL,
    [CorreoSoporte] NVARCHAR(100) NULL,
    [TelefonoContacto] NVARCHAR(20) NULL
);
GO

CREATE TABLE [Proveedores] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [NombreEmpresa] NVARCHAR(100) NOT NULL,
    [NitEmpresa] NVARCHAR(20) NOT NULL UNIQUE,
    [NombreContacto] NVARCHAR(100) NULL,
    [TelefonoPrincipal] NVARCHAR(20) NULL,
    [CorreoVentas] NVARCHAR(100) NULL,
    [DireccionFisica] NVARCHAR(200) NULL
);
GO

CREATE TABLE [Productos] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Categoria] INT NOT NULL REFERENCES [Categorias]([Id]),
    [Marca] INT NOT NULL REFERENCES [Marcas]([Id]),
    [NombreProducto] NVARCHAR(100) NOT NULL,
    [DescripcionLarga] NVARCHAR(MAX) NULL,
    [PrecioVenta] DECIMAL(18, 2) NOT NULL,
    [NumeroSerie] NVARCHAR(50) NULL,
    [Modelo] NVARCHAR(50) NULL,
    [EspecificacionesTecnicas] NVARCHAR(MAX) NULL,
    [Imagen] NVARCHAR(MAX) NULL
);
GO

CREATE TABLE [Resenas] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Producto] INT NOT NULL REFERENCES [Productos]([Id]),
    [Cliente] INT NOT NULL REFERENCES [Clientes]([Id]),
    [CalificacionEstrellas] INT NOT NULL,
    [Comentario] NVARCHAR(MAX) NULL,
    [FechaPublicacion] DATETIME2 NOT NULL,
    CONSTRAINT CK_Resenas_Estrellas CHECK ([CalificacionEstrellas] BETWEEN 1 AND 5)
);
GO

CREATE TABLE [Inventarios] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Producto] INT NOT NULL REFERENCES [Productos]([Id]),
    [Sucursal] INT NOT NULL REFERENCES [Sucursales]([Id]),
    [CantidadDisponible] INT NOT NULL,
    [StockMinimo] INT NOT NULL,
    [EstanteriaUbicacion] NVARCHAR(50) NULL,
    [UltimaActualizacion] DATETIME2 NULL,
    [CapacidadBodega] INT NOT NULL,
    CONSTRAINT UQ_Inventarios UNIQUE ([Producto], [Sucursal])
);
GO

CREATE TABLE [ComprasProductos] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Proveedor] INT NOT NULL REFERENCES [Proveedores]([Id]),
    [Sucursal] INT NOT NULL REFERENCES [Sucursales]([Id]),
    [FechaOrden] DATETIME2 NOT NULL,
    [EstadoOrden] NVARCHAR(30) NOT NULL,
    [TotalEstimado] DECIMAL(18, 2) NULL,
    [NotasInternas] NVARCHAR(MAX) NULL
);
GO

CREATE TABLE [DetallesOrdenesCompras] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [ComprasProducto] INT NOT NULL REFERENCES [ComprasProductos]([Id]),
    [Producto] INT NOT NULL REFERENCES [Productos]([Id]),
    [CantidadSolicitada] INT NOT NULL,
    [CostoUnitario] DECIMAL(18, 2) NOT NULL,
    [SubtotalCosto] DECIMAL(18, 2) NULL
);
GO

CREATE TABLE [Promociones] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [CodigoCupon] NVARCHAR(30) NOT NULL UNIQUE,
    [Descripcion] NVARCHAR(200) NULL,
    [PorcentajeDescuento] DECIMAL(18, 2) NOT NULL,
    [FechaInicio] DATETIME2 NOT NULL,
    [FechaFin] DATETIME2 NOT NULL,
    [EstadoActiva] BIT NOT NULL DEFAULT 0
);
GO

CREATE TABLE [Ventas] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Cliente] INT NOT NULL REFERENCES [Clientes]([Id]),
    [Sucursal] INT NOT NULL REFERENCES [Sucursales]([Id]),
    [Promocion] INT NULL REFERENCES [Promociones]([Id]),
    [FechaVenta] DATETIME2 NOT NULL,
    [EstadoVenta] NVARCHAR(30) NOT NULL,
    [TotalPagar] DECIMAL(18, 2) NULL,
    [DireccionEnvio] NVARCHAR(200) NULL
);
GO

CREATE TABLE [DetallesVentas] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Venta] INT NOT NULL REFERENCES [Ventas]([Id]),
    [Producto] INT NOT NULL REFERENCES [Productos]([Id]),
    [Cantidad] INT NOT NULL,
    [PrecioUnitarioVenta] DECIMAL(18, 2) NOT NULL,
    [DescuentoAplicado] DECIMAL(18, 2) NULL,
    [Subtotal] DECIMAL(18, 2) NULL
);
GO

CREATE TABLE [MetodosPago] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [NombreMetodo] NVARCHAR(50) NOT NULL,
    [Descripcion] NVARCHAR(200) NULL,
    [RequiereAprobacion] BIT NOT NULL DEFAULT 0,
    [Activo] BIT NOT NULL DEFAULT 0
);
GO

CREATE TABLE [Pagos] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Venta] INT NOT NULL REFERENCES [Ventas]([Id]),
    [MetodoPago] INT NOT NULL REFERENCES [MetodosPago]([Id]),
    [MontoPagado] DECIMAL(18, 2) NOT NULL,
    [FechaPago] DATETIME2 NOT NULL,
    [EstadoTransaccion] NVARCHAR(30) NOT NULL,
    [ReferenciaPasarela] NVARCHAR(100) NULL
);
GO

CREATE TABLE [Devoluciones] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Venta] INT NOT NULL REFERENCES [Ventas]([Id]),
    [MetodoPago] INT NOT NULL REFERENCES [MetodosPago]([Id]),
    [FechaSolicitud] DATE NOT NULL,
    [MotivoDevolucion] NVARCHAR(200) NOT NULL,
    [EstadoProceso] NVARCHAR(30) NOT NULL,
    [MontoReembolsado] DECIMAL(18, 2) NOT NULL
);
GO

CREATE TABLE [Garantias] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [DetalleVenta] INT NOT NULL REFERENCES [DetallesVentas]([Id]),
    [FechaSolicitud] DATE NOT NULL,
    [MotivoFalla] NVARCHAR(200) NOT NULL,
    [EstadoGarantia] NVARCHAR(30) NOT NULL,
    [ResolucionTecnica] NVARCHAR(200) NULL,
    [FechaCierre] DATE NULL
);
GO

CREATE TABLE [EmpresasPaqueteria] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [NombrePaqueteria] NVARCHAR(100) NOT NULL,
    [Nit] NVARCHAR(20) NULL,
    [Telefono] NVARCHAR(20) NULL,
    [CorreoElectronico] NVARCHAR(100) NULL
);
GO

CREATE TABLE [Envios] (
    [Id] INT NOT NULL PRIMARY KEY IDENTITY(1, 1),
    [Venta] INT NOT NULL REFERENCES [Ventas]([Id]),
    [EmpresaPaqueteria] INT NOT NULL REFERENCES [EmpresasPaqueteria]([Id]),
    [NumeroGuia] NVARCHAR(50) NOT NULL UNIQUE,
    [EstadoEnvio] NVARCHAR(30) NOT NULL,
    [FechaSalida] DATETIME2 NULL,
    [FechaEstimadaEntrega] DATE NULL,
    [FechaEntregaReal] DATE NULL,
    [CostoEnvio] DECIMAL(18, 2) NOT NULL
);
GO

